    """Return merged, disjoint intervals sorted by start.

    Overlapping or touching intervals are merged. The input is not modified.
    """
    if not intervals:
        return []

    sorted_intervals = sorted((list(interval) for interval in intervals),
                              key=lambda interval: (interval[0], interval[1]))
    merged = []

    for start, end in sorted_intervals:
